code.cpp:
class Solution {
public:
    int getWinner(vector<int>& arr, int k) {
        int current = arr[0];
        int wins = 0;
        for (int i = 1; i < (int)arr.size(); i++) {
            if (arr[i] > current) {
                current = arr[i];
                wins = 1;
            } else {
                wins++;
            }
            if (wins == k) return current;
        }
        return current;
    }
};
